        \overset{(\ref{eqn:spe_properties})}{=}
        &~
        O_{d, \mathbb{P}}\left({d^{\gamma-\ell_{\lambda}-1}}\right) \left\|  M^{-1} \Psi_{\leq \tilde{\ell}} \Sigma_{\leq \tilde{\ell}}^{1/2} \Sigma_{\leq \tilde{\ell}}^{1/2} \Psi_{\leq \tilde{\ell}}^{\top} \right\|_{2}^{2}
        \\
